[Form]
public class UPSPriceDiscPriceAttributeGroupEdit extends FormRun
{
    PriceDiscAdmTrans priceDiscAdmTrans;

    UPSGroupAll groupCodeHeader;
    UPSGroupAll groupCodeLine;

}

/// <summary>
/// Perform actions at form init
/// </summary>
public void init()
{
    if (!element.args().record() || element.args().dataset() != tableNum(PriceDiscAdmTrans))
    {
        throw error(error::wrongUseOfFunction(funcName()));
    }

    element.initPricingRule();

    super();

    UPSPricingAttributeRepository::getAllPricingAttributes();

    element.enableControls();
}

/// <summary>
/// Initialize pricing rule for trade areement depending on source level
/// </summary>
public void initPricingRule()
{
    priceDiscAdmTrans = element.args().record();

    if (!priceDiscAdmTrans.PricingRuleHeader)
    {
        priceDiscAdmTrans.setPricingRuleReference(fieldNum(PriceDiscAdmTrans, PricingRuleHeader), UPSPricingRule::createEmptyRule(UPSPricingAttributeSourceLevel::Header).RecId);
    }

    if (!priceDiscAdmTrans.PricingRuleLine)
    {
        priceDiscAdmTrans.setPricingRuleReference(fieldNum(PriceDiscAdmTrans, PricingRuleLine), UPSPricingRule::createEmptyRule(UPSPricingAttributeSourceLevel::Line).RecId);
    }

    groupCodeHeader = priceDiscAdmTrans.PricingGroupCodeHeader;
    groupCodeLine = priceDiscAdmTrans.PricingGroupCodeLine;

    priceDiscAdmTrans.dataSource().research(true);
}

/// <summary>
/// Research parent record before closing
/// </summary>
public void close()
{
    super();

    if ((priceDiscAdmTrans.PricingGroupCodeHeader != groupCodeHeader)
        || (priceDiscAdmTrans.PricingGroupCodeLine != groupCodeLine))
    {
        priceDiscAdmTrans.PricingGroupCodeHeader = groupCodeHeader;
        priceDiscAdmTrans.PricingGroupCodeLine = groupCodeLine;
        priceDiscAdmTrans.write();
    }

    priceDiscAdmTrans.dataSource().research(true);
}

/// <summary>
/// Enable/disable controls
/// </summary>
private void enableControls()
{
    boolean allowEditHeader = groupCodeHeader == UPSGroupAll::Group;
    boolean allowEditLine = groupCodeLine == UPSGroupAll::Group;

    UPSPricingRuleConditionHeader_ds.allowEdit(allowEditHeader);
    UPSPricingRuleHeader_ds.object(fieldNum(UPSPricingRule, PriceAttributeGroup)).allowEdit(allowEditHeader);
    PricingRuleConditionsHeader.visible(allowEditHeader);
    UPSPriceDiscPricingRulePreview.visible(allowEditHeader);

    UPSPricingRuleConditionLine_ds.allowEdit(allowEditLine);
    UPSPricingRuleLine_ds.object(fieldNum(UPSPricingRule, PriceAttributeGroup)).allowEdit(allowEditLine);
    PricingRuleConditionsLine.visible(allowEditLine);
    UPSPriceDiscPricingRulePreviewLine.visible(allowEditLine);
}

/// <summary>
/// Initialize query ranges
/// </summary>
public void init()
{
    super();

    QueryBuildDataSource qbdsPricingRule = UPSPricingRuleHeader_ds.queryBuildDataSource();

    qbdsPricingRule.clearLinks();
    qbdsPricingRule.clearDynalinks();

    qbdsPricingRule.addDynalink(fieldNum(UPSPricingRule, RecId), priceDiscAdmTrans, fieldNum(PriceDiscAdmTrans, PricingRuleHeader));
}

/// <summary>
/// Price group type header
/// </summary>
/// <param name = "_set">True if value should be modified</param>
/// <param name = "_pricingRule">Pricing rule</param>
/// <param name = "_codeType">Code type</param>
/// <returns>Code type</returns>
public edit UPSGroupAll groupCodeTypeHeader(boolean _set, UPSPricingRule _pricingRule, UPSGroupAll _codeType)
{
    if (_set)
    {
        groupCodeHeader = _codeType;

        if (_codeType == UPSGroupAll::All)
        {
            _pricingRule.clearPricingGroup();

            UPSPricingRuleHeader_ds.research(true);
        }
    }

    return groupCodeHeader;
}

/// <summary>
/// Header source level
/// </summary>
/// <param name = "_pricingRule">Pricing rule</param>
/// <returns>Header source level</returns>
[SysClientCacheDataMethodAttribute(false)]
public display UPSPricingAttributeSourceLevel sourceLevelHeader(UPSPricingRule _pricingRule)
{
    return UPSPricingAttributeSourceLevel::Header;
}

public display Name displayPricingAttributeName(UPSPricingRuleCondition _ruleCondition)
{
    return _ruleCondition.priceAttributeLink().AttributeName;
}

public edit Name editPricingRuleConditionValue(boolean _set, UPSPricingRuleCondition _ruleCondition, Name _name)
{
    if (_set)
    {
        _ruleCondition.ConditionValue = _name;
        _ruleCondition.write();
    }

    return UPSPricingAttributeAllowedValueLookup::getPriceAttributeValue(
        _ruleCondition.priceAttributeLink().AttributeName, 
        _ruleCondition.ConditionValue);
}

/// <summary>
/// Initialize query ranges
/// </summary>
public void init()
{
    super();

    QueryBuildDataSource qbdsPricingRule = UPSPricingRuleLine_ds.queryBuildDataSource();

    qbdsPricingRule.clearLinks();
    qbdsPricingRule.clearDynalinks();

    qbdsPricingRule.addDynalink(fieldNum(UPSPricingRule, RecId), priceDiscAdmTrans, fieldNum(PriceDiscAdmTrans, PricingRuleLine));
}

