/// <summary>
/// Line source level
/// </summary>
/// <param name = "_pricingRule">Pricing rule</param>
/// <returns>Line source level</returns>
[SysClientCacheDataMethodAttribute(false)]
public display UPSPricingAttributeSourceLevel sourceLevelLine(UPSPricingRule _pricingRule)
{
    return UPSPricingAttributeSourceLevel::Line;
}

public display Name displayPricingAttributeName(UPSPricingRuleCondition _ruleCondition)
{
    return _ruleCondition.priceAttributeLink().AttributeName;
}

public edit Name editPricingRuleConditionValue(boolean _set, UPSPricingRuleCondition _ruleCondition, Name _name)
{
    if (_set)
    {
        _ruleCondition.ConditionValue = _name;
        _ruleCondition.write();
    }

    return UPSPricingAttributeAllowedValueLookup::getPriceAttributeValue(
        _ruleCondition.priceAttributeLink().AttributeName, 
