/// <summary>
/// Logic when code is modified
/// </summary>
/// <returns>Boolean</returns>
public boolean modified()
{
    boolean ret;

    ret = super();

    element.enableControls();

    return ret;
}

/// <summary>
/// Lookup valid pricing attribute groups
/// </summary>
/// <returns>Pricing attribute group record</returns>
public Common lookupReference()
{
    SysReferenceTableLookup sysReferenceTableLookup;
    Query                   query = new Query();            
    QueryBuildDataSource    qbdsGroup = query.addDataSource(tableNum(UPSPricingAttributeGroup));

    qbdsGroup.addRange(fieldNum(UPSPricingAttributeGroup, SourceLevel)).value(queryValue(UPSPricingAttributeSourceLevel::Header));
    qbdsGroup.addRange(fieldNum(UPSPricingAttributeGroup, GroupType)).value(enum2Symbol(enumNum(UPSPricingAttributeGroupType), UPSPricingAttributeGroupType::General));

    qbdsGroup.addRange(fieldNum(UPSPricingAttributeGroup, IsValid)).value(queryValue(NoYes::Yes));

    sysReferenceTableLookup = SysReferenceTableLookup::newParameters(tableNum(UPSPricingAttributeGroup), this);
    sysReferenceTableLookup.addLookupfield(fieldNum(UPSPricingAttributeGroup, Name));
    sysReferenceTableLookup.addLookupfield(fieldNum(UPSPricingAttributeGroup, Description));

    sysReferenceTableLookup.parmQuery(query);

    return sysReferenceTableLookup.performFormLookup();
}

/// <summary>
/// Logic to be executed when pricing attribute group is modified
/// </summary>
/// <returns>True if value was modified</returns>
public boolean modified()
{
    boolean ret;

    ttsbegin;
    UPSPricingRuleHeader.clearRuleConditions();
    UPSPricingAttributeLineState::clearLineState(UPSPricingRuleHeader.TableId, UPSPricingRuleHeader.RecId);
    ttscommit;

    ret = super();

    UPSPricingRuleHeader_ds.research(true);

    return ret;
}

public void lookup()
{
    UPSPricingAttributeAllowedValueLookup::doLookUp(this, UPSPricingRuleConditionHeader.priceAttributeLink());

    super();
}

